/* ---------- films: white & sweet winemaking (ch.8), red & rosé winemaking (ch.9) ---------- */
const WFLOW=[{t:I3("cernita","tri","sorting")},{t:I3("diraspatura","éraflage","destem")},{t:I3("pigiatura","foulage","crush")},{t:I3("contatto bucce","macération pelliculaire","skin contact"),o:1},{t:I3("pressatura","pressurage","press")},{t:I3("mosto","jus","juice"),io:1},{t:I3("fermentazione alcolica","fermentation alcoolique","alcoholic fermentation")},{t:I3("travaso fecce grosse","soutirage lies grossières","rack off gross lees")},{t:I3("malolattica","malolactique","malolactic"),o:1},{t:I3("affinamento","élevage","maturation"),o:1},{t:I3("chiarifica e stabilizzazione","clarification et stabilisation","clarification and stabilisation")},{t:I3("vino in vendita","vin à vendre","wine for sale"),io:1}];
const RFLOW=[{t:I3("cernita","tri","sorting")},{t:I3("diraspatura","éraflage","destem")},{t:I3("pigiatura","foulage","crush")},{t:I3("macerazione pre","macération préfermentaire","pre-ferment maceration"),o:1},{t:I3("fermentazione sulle bucce","fermentation sur peaux","fermentation on skins")},{t:I3("macerazione post","macération post","post-ferment maceration"),o:1},{t:I3("svinatura","écoulage","drain")},{t:I3("vino fiore + pressa","goutte + presse","free run + press")},{t:I3("malolattica","malolactique","malolactic")},{t:I3("affinamento","élevage","maturation"),o:1},{t:I3("assemblaggio, chiarifica","assemblage, clarification","blending, clarification")},{t:I3("vino in vendita","vin à vendre","wine for sale"),io:1}];
FILMS.push(
{id:"white",sec:"c",ch:"wht",ic:"quiz",t:I3("Vinificazione in bianco","Vinification en blanc","White winemaking"),s:[
 {h:I3("Lo schema della vinificazione in bianco","Le schéma de la vinification en blanc","The white winemaking chart"),
  c:I3("Ecco tutte le tappe. Le uve vengono selezionate, diraspate e pigiate; a volte c'è un breve contatto con le bucce, poi la pressatura. Il mosto fermenta, il vino viene travasato via dalle fecce grossolane; la malolattica e l'affinamento sono scelte del produttore, mentre chiarifica e stabilizzazione precedono il confezionamento. Le caselle tratteggiate sono le scelte facoltative: contatto con le bucce, malolattica e affinamento.",
   "Voici toutes les étapes. Les raisins sont triés, éraflés et foulés ; parfois une courte macération pelliculaire, puis le pressurage. Le jus fermente, le vin est soutiré de ses lies grossières ; la malolactique et l'élevage sont des choix du vinificateur, tandis que clarification et stabilisation précèdent le conditionnement. Les cases en pointillé sont les options : macération pelliculaire, malolactique et élevage.",
   "Here are all the steps. Grapes are sorted, destemmed and crushed; sometimes there is brief skin contact, then pressing. The juice ferments and the wine is racked off its gross lees; malolactic conversion and maturation are the winemaker's choice, while clarification and stabilisation come before packaging. The dashed boxes are the options: skin contact, malolactic and maturation."),
  v:()=>fSvg(fFlow(WFLOW,-1,{stag:1}))},
 {h:I3("Il contatto con le bucce","Le contact avec les peaux","Skin contact"),
  c:I3("Di solito il mosto sta poco a contatto con le bucce, per ridurre il rischio di ossidazione: si pigia, si separa il mosto fiore e il resto va in pressa. Alcuni caricano la pressa con grappoli interi non pigiati: un metodo delicato, con meno ossidazione, che può dare vini più puri e fini. Per certe varietà aromatiche invece si lascia il mosto con le bucce per qualche ora, al fresco per non far partire la fermentazione, per avere più aromi e struttura.",
   "En général le jus reste peu au contact des peaux, pour réduire le risque d'oxydation : on foule, on sépare le jus de goutte et le reste part au pressoir. Certains chargent le pressoir de grappes entières non foulées : une méthode douce, avec moins d'oxydation, qui peut donner des vins plus purs et délicats. Pour certains cépages aromatiques, au contraire, on laisse le jus avec les peaux quelques heures, au frais pour éviter le départ en fermentation, pour gagner en arômes et en texture.",
   "Usually the juice spends little time in contact with the skins to reduce the risk of oxidation: grapes are crushed, the free-run juice is separated and the rest goes to the press. Some winemakers load the press with whole, uncrushed bunches: a gentle method with less oxidation that can give purer, more delicate wines. For some aromatic varieties, by contrast, the juice is left on the skins for a few hours, cool enough to stop fermentation starting, for more flavour intensity and texture."),
  v:()=>fSvg(fPress(20,60,WHITE,"#a9b94a")+fT(75,150,w3("grappoli interi","grappes entières","whole bunches"),9)+STEEL(190,50,90,110,{col:"#d6d27a",lv:.7,cold:1})+Array.from({length:10},(_,i)=>`<circle cx="${200+(i*9)%70}" cy="${100+(i%3)*14}" r="3" fill="#a9b94a"/>`).join("")+fClock(300,40,w3("ore","heures","hours"))+fT(235,182,w3("aromatiche: poche ore al fresco","aromatiques : quelques heures au frais","aromatic: a few cool hours"),9))},
 {h:I3("La limpidezza del mosto","La clarté du jus","Juice clarity"),
  c:I3("Il mosto appena pressato contiene frammenti di bucce e polpa: se fermentasse così potrebbe dare odori sgradevoli o fermarsi. Per questo si chiarifica prima della fermentazione, con le stesse tecniche usate per il vino: decantazione, centrifuga, collaggio e filtrazione. Alcuni produttori lasciano un po' di queste parti solide: rendono il vino meno sensibile all'ossidazione e aggiungono complessità e consistenza, ma con il rischio di difetti, quindi raramente per i vini dal carattere varietale puro.",
   "Le jus fraîchement pressé contient des fragments de peaux et de pulpe : s'il fermentait ainsi, il pourrait donner des odeurs désagréables ou s'arrêter. On le clarifie donc avant la fermentation, avec les mêmes techniques que pour le vin : débourbage, centrifugation, collage et filtration. Certains vinificateurs gardent un peu de ces bourbes : elles rendent le vin moins sensible à l'oxydation et ajoutent complexité et texture, mais avec un risque de défauts, donc rarement pour les vins au caractère variétal pur.",
   "Freshly pressed juice contains fragments of skin and pulp: fermented like that it can develop unpleasant aromas or even stop. So it is clarified before fermentation using the same techniques as for wine: settling, centrifugation, fining and filtration. Some winemakers keep a small amount of these solids: they make the wine less prone to oxidation and add complexity and texture, but with a risk of off-flavours, so rarely for wines meant to show pure varietal character."),
  v:()=>fSvg(STEEL(60,40,100,130,{col:"#c9be72",colTo:WHITE,cd:4,lv:.8,sed:1,cold:1})+fCentrifuge(230,120)+fFilterSurface(280,180)+fChip(110,186,w3("decantazione","débourbage","settling")))},
 {h:I3("Temperatura e recipiente di fermentazione","Température et contenant de fermentation","Fermentation temperature and vessel"),
  c:I3("La temperatura ideale per i bianchi è tra 12 e 22 °C. Troppo bassa dà aromi di caramella inglese, la pear drop, e non cattura il frutto della varietà; più alta favorisce aromi complessi non fruttati ma rischia di perdere il carattere varietale. In acciaio si usa il controllo di temperatura; i bianchi possono fermentare anche in barrique, dove la temperatura è più difficile da controllare, ma il volume piccolo e le cantine fresche disperdono il calore: si resta comunque verso l'alto dell'intervallo.",
   "La température idéale pour les blancs est entre 12 et 22 °C. Trop basse, elle donne des arômes de bonbon anglais, pear drop, et ne capte pas le fruit du cépage ; plus haute, elle favorise des arômes complexes non fruités mais risque de perdre le caractère variétal. En inox on utilise la régulation thermique ; les blancs peuvent aussi fermenter en barrique, où la température est plus difficile à maîtriser, mais le petit volume et les caves fraîches dissipent la chaleur : on reste toutefois plutôt en haut de la fourchette.",
   "The ideal temperature for white fermentations is 12–22 °C. Too low gives pear-drop aromas and fails to capture varietal fruit; higher temperatures encourage complex, non-fruit aromas but risk losing varietal character. Stainless steel vessels use temperature control; whites can also be fermented in barrels, where control is harder, but their small size and cool cellars dissipate heat well: they still tend to run at the higher end of the range."),
  v:()=>fSvg(`<rect x="30" y="80" width="260" height="14" rx="7" fill="url(#wt)"/><defs><linearGradient id="wt"><stop offset="0" stop-color="#4fa8a2"/><stop offset=".5" stop-color="#e9dc8c"/><stop offset="1" stop-color="#d9774b"/></linearGradient></defs>`+fT(30,110,"12 °C",9,"#fff4dc","start")+fT(290,110,"22 °C",9,"#fff4dc","end")+fChip(70,60,"pear drop","#4fa8a2")+fChip(250,60,w3("complessità, meno varietale","complexité, moins variétal","complexity, less varietal"),"#d9774b")+STEEL(60,124,60,60,{col:WHITE,lv:.7,cold:1})+fBarrel(240,160,.9)+fT(240,196,w3("barrique: parte alta","barrique : haut de fourchette","barrel: higher end"),8.5))},
 {h:I3("Dopo la fermentazione","Après la fermentation","After fermentation"),
  c:I3("Il produttore sceglie se affinare in rovere o in recipienti inerti, magari con doghe o trucioli; se usare le fecce fini per dare consistenza e aromi; se permettere o bloccare la malolattica. Poi l'assemblaggio: per i vini fruttati serve soprattutto a garantire costanza, mentre per varietà neutre come lo Chardonnay si uniscono partite con più o meno fecce, malolattica e legno per un vino più complesso. Quasi tutti i bianchi si chiarificano e si filtrano, perché ogni velatura si vede; se c'è zucchero residuo si può filtrare sterile.",
   "Le vinificateur choisit d'élever en chêne ou en contenant inerte, éventuellement avec douelles ou copeaux ; d'utiliser ou non les lies fines pour la texture et les arômes ; d'autoriser ou bloquer la malolactique. Puis l'assemblage : pour les vins fruités il sert surtout à la régularité, tandis que pour des cépages neutres comme le Chardonnay on réunit des lots avec plus ou moins de lies, de malolactique et de bois pour un vin plus complexe. Presque tous les blancs sont collés et filtrés, car le moindre trouble se voit ; s'il reste du sucre on peut filtrer stérile.",
   "The winemaker chooses whether to mature in oak or inert vessels, perhaps with staves or chips; whether to use the fine lees for texture and flavour; and whether to allow or block MLF. Then blending: for fruity styles it is mostly about consistency, while for neutral varieties such as Chardonnay batches with varying lees contact, MLF and oak are combined for complexity. Most whites are fined and/or filtered because any haze shows; wines with residual sugar may be sterile filtered."),
  v:()=>fSvg(fBox(16,24,90,36,w3("rovere o inerte","chêne ou inerte","oak or inert")) +fBox(116,24,90,36,w3("fecce fini","lies fines","fine lees"))+fBox(216,24,90,36,w3("malolattica sì/no","malolactique oui/non","MLF yes/no"))+fD(1,[0,1,2].map(i=>`<g transform="translate(${70+i*40} 110)">${fBarrel(0,0,.5,{cut:1,col:["#efe3a0","#e9dc8c","#f3e9b0"][i]})}</g>`).join("")+fArrow("M190 110H220")+STEEL(226,80,70,90,{col:WHITE,lv:.75}))+fChip(110,170,w3("assemblaggio","assemblage","blending")))},
 {h:I3("I bianchi economici","Les blancs bon marché","Inexpensive white wines"),
  c:I3("Vini semplici e di buon valore, non fatti per invecchiare. Spesso Chardonnay e Pinot Grigio, neutri e facili da maturare nei climi caldi, a volte Sauvignon Blanc. Si lavora in modo protettivo con la solforosa; le uve vengono diraspate, pigiate e pressate, e l'acidificazione è frequente. Il mosto si chiarifica molto, con centrifuga o filtro per far presto, e fermenta al fresco in acciaio con lieviti selezionati. La malolattica si blocca con freddo e solforosa, salvo per uno Chardonnay burroso; il gusto di legno arriva da trucioli o doghe. Lo zucchero residuo si aggiunge alla fine con mosto o mosto concentrato rettificato. Si stabilizza, si chiarifica, si filtra sterile e si corregge la solforosa all'imbottigliamento.",
   "Des vins simples et de bon rapport, pas faits pour vieillir. Souvent Chardonnay et Pinot Grigio, neutres et faciles à mûrir en climat chaud, parfois Sauvignon Blanc. On travaille de façon protectrice avec le soufre ; les raisins sont éraflés, foulés et pressés, et l'acidification est fréquente. Le jus est très clarifié, par centrifugation ou filtration pour aller vite, et fermente au frais en inox avec des levures sélectionnées. La malolactique est bloquée par le froid et le soufre, sauf pour un Chardonnay beurré ; le goût boisé vient de copeaux ou douelles. Le sucre résiduel s'ajoute à la fin avec du jus ou du moût concentré rectifié. On stabilise, colle, filtre stérile et ajuste le soufre à la mise en bouteille.",
   "Simple, good-value wines not made to age. Often Chardonnay and Pinot Grigio, neutral and easy to ripen in warm climates, sometimes Sauvignon Blanc. Handling is protective with SO₂; grapes are destemmed, crushed and pressed, and acidification is common. The juice is heavily clarified, by centrifuge or filter to save time, and fermented cool in stainless steel with commercial yeast. MLF is blocked with chilling and SO₂, except for a buttery Chardonnay; oak flavour comes from chips or staves. Residual sugar is added at the end as grape juice or RCGM. The wine is stabilised, fined, sterile filtered and topped up with SO₂ at bottling."),
  v:()=>fSvg(fFlow([{t:I3("acidificazione","acidification","acidification")},{t:I3("centrifuga","centrifugation","centrifuge")},{t:I3("acciaio freddo, lieviti selezionati","inox froid, levures sélectionnées","cool steel, cultured yeast")},{t:I3("niente MLF","pas de FML","no MLF")},{t:I3("trucioli","copeaux","chips"),o:1},{t:I3("zucchero: mosto o MCR","sucre : jus ou MCR","sugar: juice or RCGM"),o:1},{t:I3("filtrazione sterile","filtration stérile","sterile filtration")},{t:I3("SO₂ in bottiglia","SO₂ en bouteille","SO₂ at bottling")}],-1,{stag:1,y0:30,bh:34,gy:20}))},
 {h:I3("Le uve aromatiche: Sauvignon Blanc e Riesling","Les cépages aromatiques : Sauvignon Blanc et Riesling","Aromatic varieties: Sauvignon Blanc and Riesling"),
  c:I3("Hanno aromi pronunciati, come anche Moscato, Gewurztraminer e Torrontés: l'obiettivo è conservarli. Il Sauvignon Blanc, aromatico e acido, matura presto e ama i climi freschi: nella Loira, a Sancerre e Pouilly-Fumé, dà mela verde, asparago e pietra bagnata; a Marlborough, fresco ma molto soleggiato, uva spina, fiori di sambuco, pompelmo e frutto della passione. Il Riesling resiste al freddo, germoglia tardi e accumula zucchero senza perdere acidità: dà vini dal secco al molto dolce, anche botritizzati, e invecchia per decenni sviluppando miele, tostato e note di idrocarburo.",
   "Ils ont des arômes marqués, comme le Muscat, le Gewurztraminer et le Torrontés : le but est de les préserver. Le Sauvignon Blanc, aromatique et acide, mûrit tôt et aime les climats frais : dans la Loire, à Sancerre et Pouilly-Fumé, il donne pomme verte, asperge et pierre mouillée ; à Marlborough, frais mais très ensoleillé, groseille à maquereau, fleur de sureau, pamplemousse et fruit de la passion. Le Riesling résiste au froid, débourre tard et accumule du sucre sans perdre son acidité : il donne des vins du sec au très doux, aussi botrytisés, et vieillit des décennies en développant miel, toasté et notes de pétrole.",
   "They have pronounced aromas, like Muscat, Gewurztraminer and Torrontés: the aim is to keep them. Sauvignon Blanc, aromatic and high in acid, ripens early and suits cool climates: in the Loire, at Sancerre and Pouilly-Fumé, it gives green apple, asparagus and wet pebbles; in Marlborough, cool but intensely sunny, gooseberry, elderflower, grapefruit and passion fruit. Riesling is hardy in cold winters, buds late and builds sugar without losing acidity: it makes wines from dry to lusciously sweet, including botrytised ones, and ages for decades, developing honey, toast and petrol notes."),
  v:()=>fSvg(`<g transform="translate(80 70)">${fBunch(0,0,2,"#c9d26a")}</g><g transform="translate(240 70)">${fBunch(0,0,2,"#d8d88a")}</g>`+fT(80,40,"Sauvignon Blanc",11)+fT(240,40,"Riesling",11)+fD(1,fChip(80,140,w3("Loira: mela verde, asparago","Loire : pomme verte, asperge","Loire: green apple, asparagus"))+fChip(80,164,w3("Marlborough: uva spina, maracuja","Marlborough : groseille, passion","Marlborough: gooseberry, passion fruit")))+fD(2,fChip(240,140,w3("dal secco al dolce","du sec au doux","dry to sweet"))+fChip(240,164,w3("miele, idrocarburo","miel, pétrole","honey, petrol"))))},
 {h:I3("Le scelte per le uve aromatiche","Les choix pour les cépages aromatiques","Winemaking choices for aromatic grapes"),
  c:I3("Uva e mosto si trattano con delicatezza e solforosa sotto controllo; in pressa vanno uva pigiata o grappoli interi, subito o dopo un breve contatto con le bucce. Il mosto si chiarifica dolcemente, per decantazione. Si fermenta in recipienti inerti, spesso acciaio, come in Nuova Zelanda; in Alsazia il Riesling può fermentare in grandi botti vecchie, i foudres, che danno un po' di ossidazione e consistenza senza aromi di legno. Fermentazione fresca e lenta. Il Sauvignon finisce secco; il Riesling dolce si ottiene fermando la fermentazione con freddo o solforosa, mentre con uve botritizzate si ferma da sola. La malolattica si evita con la solforosa e il vino si imbottiglia presto; Riesling e Sauvignon si assemblano raramente, salvo Sauvignon e Sémillon a Bordeaux e in Australia Occidentale.",
   "Raisin et jus sont traités délicatement, avec le soufre sous contrôle ; on charge le pressoir de raisin foulé ou de grappes entières, aussitôt ou après une courte macération. Le jus est clarifié en douceur, par débourbage. On fermente en contenant inerte, souvent l'inox, comme en Nouvelle-Zélande ; en Alsace le Riesling peut fermenter en grands vieux foudres, qui apportent un peu d'oxydation et de texture sans arômes boisés. Fermentation fraîche et lente. Le Sauvignon finit sec ; le Riesling doux s'obtient en arrêtant la fermentation par le froid ou le soufre, tandis qu'avec des raisins botrytisés elle s'arrête seule. On évite la malolactique avec du soufre et on embouteille tôt ; Riesling et Sauvignon s'assemblent rarement, sauf Sauvignon et Sémillon à Bordeaux et en Australie-Occidentale.",
   "Grapes and juice are handled gently with SO₂ monitored; crushed fruit or whole bunches go to the press, immediately or after brief skin contact. The juice is clarified gently, by settling. Fermentation is in inert vessels, often stainless steel, as in New Zealand; in Alsace Riesling may ferment in large old oak foudres, adding a little oxidation and texture without oak flavour. Fermentation is cool and slow. Sauvignon is fermented dry; sweet Riesling is made by stopping fermentation with chilling or SO₂, while with botrytised grapes it stops naturally. MLF is avoided with SO₂ and the wine is bottled early; both are rarely blended, except Sauvignon with Sémillon in Bordeaux and Western Australia."),
  v:()=>fSvg(STEEL(20,50,80,110,{col:WHITE,lv:.75,cold:1,bub:6,lab:w3("Nuova Zelanda","Nouvelle-Zélande","New Zealand")})+`<ellipse cx="170" cy="110" rx="50" ry="46" fill="url(#fwood)" stroke="#4e321c"/>`+fT(170,176,"foudre · Alsace",9)+fD(1.5,fBox(232,40,80,50,w3("niente MLF, imbottigliato presto","pas de FML, mise en bouteille rapide","no MLF, bottled early"),{fill:"rgba(140,29,64,.55)"})))},
 {h:I3("Sauvignon in barrique: Fumé Blanc e Pessac-Léognan","Sauvignon en barrique : Fumé Blanc et Pessac-Léognan","Barrel Sauvignon: Fumé Blanc and Pessac-Léognan"),
  c:I3("Per lo stile cremoso e speziato di alcuni Fumé Blanc californiani e dei bianchi di Pessac-Léognan, a Bordeaux, il Sauvignon Blanc fermenta in barrique, spesso con lieviti indigeni per più complessità. Poi resta alcuni mesi sulle fecce, durante i quali di solito fa la malolattica, e almeno una parte del vino affina in rovere nuovo. A Pessac-Léognan si assembla con il Sémillon, che aggiunge corpo e ricchezza.",
   "Pour le style crémeux et épicé de certains Fumé Blanc californiens et des blancs de Pessac-Léognan, à Bordeaux, le Sauvignon Blanc fermente en barrique, souvent avec des levures indigènes pour plus de complexité. Il reste ensuite plusieurs mois sur lies, pendant lesquels il fait en général sa malolactique, et au moins une partie du vin s'élève en chêne neuf. À Pessac-Léognan on l'assemble au Sémillon, qui apporte corps et richesse.",
   "For the creamy, spicy style of some Californian Fumé Blanc and the whites of Pessac-Léognan in Bordeaux, Sauvignon Blanc is barrel-fermented, often with ambient yeast for complexity. It then spends several months on its lees, usually going through MLF, and at least part of the wine is matured in new oak. In Pessac-Léognan it is blended with Sémillon, which adds body and richness."),
  v:()=>fSvg([0,1,2].map(i=>fBarrel(70+i*90,110,1.2,{cut:1,col:WHITE})).join("")+fChip(160,40,w3("fermentazione in barrique + fecce + MLF","fermentation en barrique + lies + FML","barrel ferment + lees + MLF"))+fChip(160,180,"Sauvignon + Sémillon"))},
 {h:I3("Le uve meno aromatiche: Chardonnay e Pinot Gris","Les cépages moins aromatiques : Chardonnay et Pinot Gris","Less aromatic grapes: Chardonnay and Pinot Gris"),
  c:I3("Più neutre, lasciano al produttore un ruolo più attivo nello stile. Lo Chardonnay matura facilmente ovunque, ma germoglia presto e teme le gelate: nei climi freschi dà mela verde e agrumi, nei moderati pesca bianca e melone, nei caldi banana e ananas. In Borgogna va da Chablis, acido e minerale, alla Côte d'Or, frutta a nocciolo e rovere cremoso, al Mâconnais, più maturo; quasi tutti fanno la malolattica e molti un lungo affinamento sulle fecce, e invecchiando sviluppano note di nocciola e fungo. Il Pinot Gris d'Alsazia è secco o abboccato, untuoso, con frutta tropicale, zenzero e miele; il Pinot Grigio del Nord-Est italiano è secco e intenso, mentre quello economico del Veneto, da cloni a buccia chiara e polpa abbondante, è neutro.",
   "Plus neutres, ils laissent au vinificateur un rôle plus actif dans le style. Le Chardonnay mûrit facilement partout, mais débourre tôt et craint les gelées : en climat frais il donne pomme verte et agrumes, en climat modéré pêche blanche et melon, en climat chaud banane et ananas. En Bourgogne il va de Chablis, vif et minéral, à la Côte d'Or, fruits à noyau et boisé crémeux, au Mâconnais, plus mûr ; presque tous font leur malolactique et beaucoup un long élevage sur lies, et en vieillissant ils développent noisette et champignon. Le Pinot Gris d'Alsace est sec ou demi-sec, onctueux, avec fruits tropicaux, gingembre et miel ; le Pinot Grigio du Nord-Est italien est sec et intense, tandis que celui, bon marché, de Vénétie, issu de clones à peau claire et pulpe abondante, est neutre.",
   "More neutral, they give the winemaker a more active role in shaping style. Chardonnay ripens easily almost anywhere but buds early and fears frost: in cool climates it gives green apple and citrus, in moderate ones white peach and melon, in hot ones banana and pineapple. In Burgundy it ranges from Chablis, high-acid and stony, to the Côte d'Or, stone fruit and creamy oak, to the riper Mâconnais; nearly all go through MLF and many get extended lees ageing, developing nutty and mushroom notes with age. Alsace Pinot Gris is dry or off-dry, oily, with tropical fruit, ginger and honey; north-east Italian Pinot Grigio is dry and intense, while inexpensive Veneto Pinot Grigio, from a pale-skinned, fleshy clone, is neutral."),
  v:()=>fSvg(`<path d="M20 150H300" stroke="url(#ch)" stroke-width="12" stroke-linecap="round"/><defs><linearGradient id="ch"><stop offset="0" stop-color="#9cc65a"/><stop offset=".5" stop-color="#f0d27a"/><stop offset="1" stop-color="#f3b34a"/></linearGradient></defs>`+fT(30,176,w3("fresco: mela, agrumi","frais : pomme, agrumes","cool: apple, citrus"),8.5,"#fff4dc","start")+fT(160,194,w3("moderato: pesca, melone","modéré : pêche, melon","moderate: peach, melon"),8.5)+fT(300,176,w3("caldo: banana, ananas","chaud : banane, ananas","hot: banana, pineapple"),8.5,"#fff4dc","end")+fD(.8,fChip(70,40,"Chablis")+fChip(160,40,"Côte d'Or")+fChip(250,40,"Mâconnais"))+fD(1.6,fChip(160,90,"Pinot Gris (Alsace) · Pinot Grigio (Italia)","#8a5a6a")))},
 {h:I3("Le scelte per Chardonnay e Pinot Gris","Les choix pour Chardonnay et Pinot Gris","Choices for Chardonnay and Pinot Gris"),
  c:I3("Le uve si pigiano o, spesso per lo Chardonnay, vanno in pressa a grappolo intero; per alcune varietà neutre un'esposizione controllata all'ossigeno in questa fase migliorerebbe la longevità. Il mosto si chiarifica dolcemente e a volte si lasciano parti solide per complessità. Si fermenta in acciaio o cemento per la freschezza, come a Chablis, nel Nord-Est italiano e in Nuova Zelanda; in grandi botti vecchie per il Pinot Gris d'Alsazia; in piccole barrique nuove per lo Chardonnay della Côte d'Or. Il residuo zuccherino si ottiene fermando la fermentazione, in Nuova Zelanda, o naturalmente, in Alsazia. Poi barrique nuove per il tostato, botti vecchie e grandi per un'ossidazione dolce, o acciaio per la freschezza; malolattica per rotondità, quasi sempre in Borgogna, Chablis compreso; lungo contatto con le fecce e bâtonnage, cioè rimescolarle con un bastone.",
   "Les raisins sont foulés ou, souvent pour le Chardonnay, pressés en grappes entières ; pour certains cépages neutres, une exposition contrôlée à l'oxygène à ce stade améliorerait l'aptitude au vieillissement. Le jus est clarifié en douceur, en gardant parfois des bourbes pour la complexité. On fermente en inox ou en béton pour la fraîcheur, comme à Chablis, dans le Nord-Est italien et en Nouvelle-Zélande ; en grands vieux foudres pour le Pinot Gris d'Alsace ; en petites barriques neuves pour le Chardonnay de la Côte d'Or. Le sucre résiduel s'obtient en arrêtant la fermentation, en Nouvelle-Zélande, ou naturellement, en Alsace. Puis barriques neuves pour le toasté, vieux grands fûts pour une oxydation douce, ou inox pour la fraîcheur ; malolactique pour la rondeur, presque toujours en Bourgogne, Chablis compris ; long contact sur lies et bâtonnage, c'est-à-dire remise en suspension des lies avec un bâton.",
   "Grapes are crushed or, often for Chardonnay, whole-bunch pressed; for some neutral varieties controlled oxygen exposure at this stage is thought to improve ageing. The juice is gently clarified, sometimes keeping some solids for complexity. Fermentation is in steel or concrete for freshness, as in Chablis, north-east Italy and New Zealand; in large old oak for Alsace Pinot Gris; in small new barrels for Côte d'Or Chardonnay. Residual sugar comes from stopping fermentation, in New Zealand, or naturally, in Alsace. Then new barriques for toast, older larger casks for gentle oxidation, or steel for freshness; MLF for a rounder texture, almost universal in Burgundy including Chablis; long fine-lees contact and lees stirring, mixing the lees back in with a rod."),
  v:()=>fSvg(fBarrel(110,110,2.2,{cut:1,col:WHITE})+`<g><animateTransform attributeName="transform" type="rotate" values="-14 110 50;14 110 50;-14 110 50" dur="2s" repeatCount="indefinite"/><path d="M110 10V138" stroke="#a5743f" stroke-width="5" stroke-linecap="round"/></g>${Array.from({length:12},(_,i)=>`<circle cx="${70+i*7}" cy="140" r="2" fill="#d8c79a"><animate attributeName="cy" values="142;${112-i%3*6};142" dur="${2+i%3*.4}s" repeatCount="indefinite"/></circle>`).join("")}`+fChip(250,60,"bâtonnage")+fChip(250,110,"MLF")+fChip(250,160,w3("barrique nuova","barrique neuve","new barrique")))}
]},
{id:"sweet",sec:"c",ch:"wht",ic:"guess",t:I3("I vini dolci","Les vins doux","Sweet wines"),s:[
 {h:I3("Tre modi per fare un vino dolce","Trois façons de faire un vin doux","Three ways to make a sweet wine"),
  c:I3("Quasi tutti i vini fermentano fino al secco: i lieviti consumano tutto lo zucchero. I vini dolci contengono zucchero non fermentato e si ottengono in tre modi: fermando la fermentazione, aggiungendo un componente dolce, oppure concentrando lo zucchero nell'uva.",
   "Presque tous les vins fermentent jusqu'au sec : les levures consomment tout le sucre. Les vins doux contiennent du sucre non fermenté et s'obtiennent de trois façons : en arrêtant la fermentation, en ajoutant un élément sucrant, ou en concentrant le sucre dans le raisin.",
   "Most wines are fermented to dryness: the yeast consume all the sugar. Sweet wines contain unfermented sugar and are made in three ways: by stopping the fermentation, by adding a sweetening component, or by concentrating the sugar in the grapes."),
  v:()=>fSvg([[I3("fermare la fermentazione","arrêter la fermentation","stop the fermentation"),"#b5334a"],[I3("aggiungere dolcezza","ajouter du sucre","add sweetness"),"#d4a23a"],[I3("concentrare gli zuccheri","concentrer les sucres","concentrate grape sugars"),"#5e8c31"]].map(([l,c],i)=>fD(i*.5,fBox(20+i*100,60,90,70,tx(l),{fill:c}))).join(""))},
 {h:I3("Fermare la fermentazione","Arrêter la fermentation","Stopping the fermentation"),
  c:I3("Il metodo tradizionale è la fortificazione: si aggiunge acquavite di vino, che uccide i lieviti, ma cambia molto l'equilibrio del vino; lo vedremo con i vini fortificati. Si può anche fermare con una forte dose di solforosa o raffreddando il vino; poi lo si filtra per togliere i lieviti, e da quel momento nessun lievito deve più toccarlo, o la fermentazione riprende. È il metodo dei Kabinett e Spätlese tedeschi di qualità e degli spumanti dolci come l'Asti, e dà vini con poco alcol.",
   "La méthode traditionnelle est le mutage : on ajoute de l'eau-de-vie de vin, qui tue les levures, mais modifie fortement l'équilibre du vin ; on le verra avec les vins mutés. On peut aussi arrêter avec une forte dose de soufre ou en refroidissant le vin ; on le filtre ensuite pour retirer les levures, et dès lors aucune levure ne doit plus le toucher, sinon la fermentation repart. C'est la méthode des Kabinett et Spätlese allemands de qualité et des effervescents doux comme l'Asti, et elle donne des vins peu alcoolisés.",
   "The traditional way is fortification: adding grape spirit kills the yeast, but radically changes the wine's balance; we will see this with fortified wines. Fermentation can also be stopped with a high dose of SO₂ or by chilling; the wine is then filtered to remove the yeast, and no yeast must touch it afterwards or fermentation will restart. This is used for high-quality German Kabinett and Spätlese and for sweet sparkling wines such as Asti, and gives low-alcohol wines."),
  v:()=>fSvg(STEEL(30,40,90,130,{col:WHITE,lv:.75,cold:1})+fThermo(130,60,"< 5 °C",.1,"#4fa8a2")+fArrow("M150 110H186")+fFilterSurface(220,150)+fArrow("M254 110H274")+fBottle(296,130,{col:WHITE,cork:1})+fChip(160,26,"Kabinett · Spätlese · Asti"))},
 {h:I3("Aggiungere dolcezza","Ajouter un élément sucrant","Adding a sweetening component"),
  c:I3("In alcuni paesi, soprattutto in Germania, i vini abboccati si ottengono aggiungendo mosto non fermentato, la Süssreserve: è mosto filtrato prima della fermentazione o protetto con solforosa, che si aggiunge al vino secco al momento dell'imbottigliamento. Lo stesso effetto si ottiene con il mosto concentrato rettificato, spesso usato per dare un po' di dolcezza ai vini economici.",
   "Dans certains pays, surtout en Allemagne, les vins demi-secs s'obtiennent en ajoutant du moût non fermenté, la Süssreserve : un jus filtré avant fermentation ou protégé par le soufre, ajouté au vin sec au moment de la mise en bouteille. On obtient le même effet avec le moût concentré rectifié, souvent utilisé pour donner un peu de douceur aux vins bon marché.",
   "In some countries, particularly Germany, medium-sweet wines are made by adding unfermented grape juice, called Süssreserve: juice filtered before fermentation or dosed with SO₂, added to the dry wine just before bottling. RCGM can achieve the same effect and is often used to add a little sweetness to inexpensive wines."),
  v:()=>fSvg(STEEL(40,50,90,120,{col:WHITE,lv:.7,lab:w3("vino secco","vin sec","dry wine")})+`<g transform="translate(220 110)"><rect x="-28" y="-40" width="56" height="70" rx="6" fill="#efe3a0"/>${fT(0,-6,"Süss-",10,"#5f1129")}${fT(0,8,"reserve",10,"#5f1129")}</g>`+fD(1,fArrow("M190 110H140",null,1))+fChip(220,186,w3("oppure MCR","ou MCR","or RCGM")))},
 {h:I3("La muffa nobile","La pourriture noble","Noble rot"),
  c:I3("Molti dei migliori vini dolci, come Sauternes, Tokaji, Beerenauslese e Trockenbeerenauslese, nascono dalla muffa nobile, causata dallo stesso fungo della muffa grigia, Botrytis cinerea. Servono condizioni precise: l'uva deve essere già pienamente matura, e il clima deve dare mattine umide e nebbiose seguite da pomeriggi asciutti e soleggiati. L'umidità del mattino fa crescere il fungo, che fora la buccia con filamenti microscopici; il sole del pomeriggio ne frena lo sviluppo e fa evaporare l'acqua, concentrando zuccheri, acidi e aromi. Il fungo aggiunge note proprie: miele, albicocca, scorza di agrumi e frutta secca.",
   "Beaucoup des meilleurs vins doux, comme Sauternes, Tokaji, Beerenauslese et Trockenbeerenauslese, naissent de la pourriture noble, causée par le même champignon que la pourriture grise, Botrytis cinerea. Il faut des conditions précises : le raisin doit être déjà pleinement mûr, et le climat doit offrir des matins humides et brumeux suivis d'après-midi secs et ensoleillés. L'humidité du matin fait croître le champignon, qui perce la peau de filaments microscopiques ; le soleil de l'après-midi freine son développement et fait évaporer l'eau, concentrant sucres, acides et arômes. Le champignon ajoute ses propres notes : miel, abricot, zeste d'agrumes et fruits secs.",
   "Many of the finest sweet wines, such as Sauternes, Tokaji, Beerenauslese and Trockenbeerenauslese, come from noble rot, caused by the same fungus as grey rot, Botrytis cinerea. Specific conditions are needed: the grapes must already be fully ripe, and the region must give humid, misty mornings followed by dry, sunny afternoons. The morning damp lets the rot develop, puncturing the skin with microscopic filaments; the afternoon sun slows the rot and evaporates water, concentrating sugars, acids and flavours. The fungus adds its own notes: honey, apricot, citrus zest and dried fruit."),
  v:()=>fSvg(fGround()+fVine("ripe")+`<rect x="0" y="80" width="320" height="70" fill="#fff" opacity=".6"><animate attributeName="opacity" values=".7;.7;0;0;.7" dur="6s" repeatCount="indefinite"/></rect>`+`<g opacity="0">${fSun(280,36,14)}<animate attributeName="opacity" values="0;0;1;1;0" dur="6s" repeatCount="indefinite"/></g>`+[124,172,220].map(x=>`<g transform="translate(${x+4} 128)">${[0,1,2,3].map(k=>`<circle cx="${(k%2)*5-2}" cy="${Math.floor(k/2)*5}" r="2.6" fill="#a8742e"><animate attributeName="r" from="2.8" to="2" dur="3s" fill="freeze"/></circle>`).join("")}</g>`).join("")+fChip(160,24,w3("miele · albicocca · scorza d'agrumi","miel · abricot · zeste d'agrumes","honey · apricot · citrus zest")),"autumn")},
 {h:I3("Vendemmia a passaggi e rischi della botrite","Tries successives et risques du botrytis","Picking in passes and botrytis risks"),
  c:I3("La muffa nobile non si diffonde in modo uniforme: servono più passaggi a mano per scegliere gli acini migliori, un lavoro costoso di manodopera esperta per settimane. In regioni come il Sauternes le condizioni ideali non si verificano ogni anno. Se è troppo umido il fungo cresce troppo in fretta e diventa muffa grigia, che spacca gli acini e favorisce altre infezioni. Anche se è lo stesso fungo, «botrite» è spesso usato come sinonimo di muffa nobile, e in etichetta si legge «botritizzato».",
   "La pourriture noble ne se répand pas uniformément : il faut plusieurs tries à la main pour choisir les meilleures baies, un travail coûteux de main-d'œuvre qualifiée pendant des semaines. Dans des régions comme le Sauternais, les conditions idéales ne se présentent pas chaque année. S'il fait trop humide, le champignon se développe trop vite et devient pourriture grise, qui fait éclater les baies et favorise d'autres infections. Bien que ce soit le même champignon, « botrytis » est souvent employé comme synonyme de pourriture noble, et l'étiquette indique parfois « botrytisé ».",
   "Noble rot never spreads evenly: several hand pickings are needed to select the best berries, an expensive job for skilled labour over weeks. In regions such as Sauternes the ideal conditions do not occur every year. If it is too damp the fungus develops too quickly and becomes grey rot, splitting the berries and inviting infection. Although it is the same fungus, 'botrytis' is often used as a synonym for noble rot, and 'botrytised' appears on sweet wine labels."),
  v:()=>fSvg(fGround()+fVine("ripe")+[1,2,3].map(i=>fD(i*.8,fChip(40+i*70,30,`${i}ª`,"#d4a23a","#2a1b20"))).join("")+fMan(270,172,1,"#8c1d40")+`<g><circle cx="200" cy="122" r="2.8" fill="#a8742e"/><animateTransform attributeName="transform" type="translate" values="0 0;60 30;60 30" dur="1.6s" repeatCount="indefinite"/></g>`+fD(2.6,fChip(90,140,w3("troppa umidità: muffa grigia","trop humide : pourriture grise","too damp: grey rot"),"#5c646b")),"autumn")},
 {h:I3("Appassimento in pianta","Passerillage sur souche","Drying grapes on the vine"),
  c:I3("Quando l'uva ha raggiunto la piena maturazione zuccherina può iniziare a disidratarsi e ad appassire sulla pianta, il passerillage, concentrando lo zucchero nel succo. Servono autunni caldi e asciutti, altrimenti compare la muffa grigia. Questi vini hanno note di frutta stramatura, secca e tropicale, e una consistenza ricca; a volte in etichetta si legge Late Harvest, vendemmia tardiva.",
   "Quand le raisin a atteint sa pleine maturité en sucre, il peut commencer à se déshydrater et à passeriller sur souche, concentrant le sucre dans le jus. Il faut des automnes chauds et secs, sinon la pourriture grise apparaît. Ces vins ont des notes de fruits surmûris, secs et tropicaux, et une texture riche ; l'étiquette indique parfois Late Harvest, vendanges tardives.",
   "Once grapes reach full sugar ripeness they can start to dehydrate and shrivel on the vine, called passerillage, concentrating the sugar in the juice. Warm, dry autumns are needed, otherwise grey rot develops. These wines show over-ripe, dried and tropical fruit and a rich texture; they are sometimes labelled Late Harvest."),
  v:()=>fSvg(fSun(280,36,16)+fGround()+fVine("ripe")+[100,148,196].map(x=>`<g transform="translate(${x+4} 120)">${fBunch(0,0,1,"#6b2d5c")}<animateTransform attributeName="transform" type="scale" from="1" to=".75" dur="4s" fill="freeze" additive="sum"/></g>`).join("")+fChip(80,24,"Late Harvest"),"autumn")},
 {h:I3("Appassimento dopo la raccolta","Passerillage après la récolte","Drying grapes after picking"),
  c:I3("Uve sane vengono raccolte e messe ad appassire, così perdono acqua e concentrano lo zucchero. Servono condizioni asciutte e calde, e bisogna eliminare tutti gli acini marci prima che la muffa si diffonda. È la tecnica dei passiti italiani, come il Recioto della Valpolicella DOCG, che possono avere una nota di uva passa.",
   "Des raisins sains sont récoltés et mis à sécher, perdant de l'eau et concentrant leur sucre. Il faut des conditions sèches et chaudes, et retirer toutes les baies pourries avant que la pourriture ne s'étende. C'est la technique des passiti italiens, comme le Recioto della Valpolicella DOCG, qui peuvent avoir une note de raisin sec.",
   "Healthy grapes are picked and left to dry, losing water and concentrating their sugar. Conditions must be dry and warm, and all rotten grapes must be removed or the rot will spread. This technique makes Italy's passito wines, such as Recioto della Valpolicella DOCG, which can show a raisiny quality."),
  v:()=>fSvg([0,1,2].map(r=>`<rect x="40" y="${60+r*40}" width="240" height="4" fill="#8a5a33"/>${[0,1,2,3,4,5].map(k=>`<g transform="translate(${62+k*38} ${48+r*40})">${fBunch(0,0,1,"#7a4a2a")}<animateTransform attributeName="transform" type="scale" from="1" to=".72" dur="5s" fill="freeze" additive="sum"/></g>`).join("")}`).join("")+[0,1,2].map(i=>`<path d="M10 ${70+i*40}h24" stroke="#bfe3f5" stroke-width="2" stroke-linecap="round"><animateTransform attributeName="transform" type="translate" from="0 0" to="40 0" dur="1.4s" begin="${i*.3}s" repeatCount="indefinite"/></path>`).join("")+fChip(160,190,"Recioto della Valpolicella"))},
 {h:I3("Il congelamento: Eiswein e Icewine","Le gel : Eiswein et Icewine","Freezing: Eiswein and Icewine"),
  c:I3("Uve sane vengono lasciate sulla pianta fino all'inverno. Quando arriva il gelo, l'acqua nella polpa diventa ghiaccio; raccogliendole e pressandole ancora congelate, il ghiaccio resta nella pressa ed esce un succo molto più zuccherino. Così si fanno l'Eiswein tedesco e l'Icewine canadese, vini dal carattere varietale molto puro. Lo stesso effetto si può ottenere congelando l'uva in cantina.",
   "Des raisins sains sont laissés sur souche jusqu'à l'hiver. Quand le gel arrive, l'eau de la pulpe se transforme en glace ; en les cueillant et les pressant encore gelés, la glace reste dans le pressoir et il s'écoule un jus bien plus sucré. Ainsi se font l'Eiswein allemand et l'Icewine canadien, vins au caractère variétal très pur. On peut obtenir le même effet en congelant le raisin au chai.",
   "Healthy grapes are left hanging on the vine into winter. When freezing temperatures arrive, the water in the pulp turns to ice; picked and pressed while still frozen, the ice stays in the press and the juice that runs out is much richer in sugar. This makes German Eiswein and Canadian Icewine, wines with very pure varietal character. The same effect can be replicated by freezing picked grapes at the winery."),
  v:()=>fSvg(fMoon(270,30)+fSnow()+fGround("#e9eef2")+fVine("ripe",-40)+fThermo(250,70,"−7 °C",.08,"#4fa8a2")+fD(1.5,fChip(80,190,"Eiswein · Icewine","#2b7a75")),"night")},
 {h:I3("Una fermentazione che si ferma da sola","Une fermentation qui s'arrête seule","A fermentation that stops by itself"),
  c:I3("Quando i vini dolci nascono da uve concentrate, la fermentazione si ferma naturalmente quando i lieviti hanno trasformato in alcol tutto lo zucchero che riescono. Questo può accadere a gradi alcolici bassi, a volte appena il 7 per cento, perché i lieviti faticano a sopravvivere in ambienti così zuccherini. I Trockenbeerenauslese tedeschi sono l'esempio classico.",
   "Quand les vins doux naissent de raisins concentrés, la fermentation s'arrête naturellement lorsque les levures ont transformé en alcool tout le sucre qu'elles peuvent. Cela peut arriver à des degrés bas, parfois à peine 7 %, car les levures peinent à survivre dans un milieu si sucré. Les Trockenbeerenauslese allemands en sont l'exemple classique.",
   "When sweet wines are made from concentrated grapes, fermentation stops naturally once the yeast have converted as much sugar into alcohol as they can. This can happen at quite low alcohol levels, sometimes as low as 7% abv, because yeast struggle to survive in such sugary environments. German Trockenbeerenauslese is the classic example."),
  v:()=>fSvg(STEEL(110,40,100,130,{col:"#d99a2b",lv:.75,bub:4})+fYeast(150,120)+fD(1.5,`<path d="M140 110l20 20M160 110l-20 20" stroke="#b5334a" stroke-width="3"/>`)+fChip(260,80,"≈ 7% vol","#d4a23a","#2a1b20")+fChip(260,130,"TBA"))}
]},
{id:"red",sec:"c",ch:"red",ic:"sat",t:I3("Vinificazione in rosso: estrazione e fermentazione","Vinification en rouge : extraction et fermentation","Red winemaking: extraction and fermentation"),s:[
 {h:I3("Lo schema della vinificazione in rosso","Le schéma de la vinification en rouge","The red winemaking chart"),
  c:I3("La chiave del rosso è estrarre colore e tannini dalle bucce delle uve nere, che quindi fermentano insieme al mosto. Da qui due conseguenze: ci sono molte più scelte prima, durante e dopo la fermentazione rispetto al bianco, e la pressatura avviene dopo la fermentazione, non prima. Inoltre nei rossi la malolattica è la norma, non una scelta di stile. Ecco lo schema con le uve diraspate e pigiate.",
   "La clé du rouge est d'extraire couleur et tanins des peaux des raisins noirs, qui fermentent donc avec le jus. Deux conséquences : il y a bien plus de choix avant, pendant et après la fermentation qu'en blanc, et le pressurage a lieu après la fermentation, pas avant. De plus, en rouge la malolactique est la règle, pas un choix de style. Voici le schéma avec raisins éraflés et foulés.",
   "The key to red wine is extracting colour and tannin from black grape skins, so the skins are fermented with the juice. Two consequences follow: there are far more options before, during and after fermentation than for whites, and pressing happens after fermentation, not before. Also, in red winemaking malolactic conversion is standard practice, not a style choice. Here is the chart for destemmed, crushed fruit."),
  v:()=>fSvg(fFlow(RFLOW,-1,{stag:1}))},
 {h:I3("La macerazione prefermentativa a freddo","La macération préfermentaire à froid","Cold soaking"),
  c:I3("Quasi tutta l'uva per i rossi viene diraspata e pigiata. Alcuni produttori lasciano poi macerare l'uva pigiata a bassa temperatura prima che parta la fermentazione: è la macerazione a freddo, che estrae colore e aromi. I tannini invece si sciolgono meglio in presenza di alcol, quindi in questa fase se ne estraggono pochi.",
   "Presque tout le raisin pour les rouges est éraflé et foulé. Certains vinificateurs laissent ensuite macérer le raisin foulé à basse température avant le départ de la fermentation : c'est la macération à froid, qui extrait couleur et arômes. Les tanins, eux, se dissolvent mieux en présence d'alcool, donc on en extrait peu à ce stade.",
   "Most fruit for red wine is destemmed and crushed. Some winemakers then let the crushed grapes macerate at a low temperature before fermentation starts: this is cold soaking, which extracts colour and flavour compounds. Tannins dissolve better in alcoholic solutions, so little tannin is extracted at this point."),
  v:()=>fSvg(STEEL(110,40,100,130,{col:"#b04a6a",colTo:RED,cd:5,lv:.8,cold:1})+Array.from({length:12},(_,i)=>`<circle cx="${120+(i*13)%80}" cy="${90+(i%4)*16}" r="3" fill="#3d0f22"/>`).join("")+fThermo(240,60,w3("freddo","froid","cold"),.15,"#4fa8a2")+fChip(70,60,w3("colore, aromi","couleur, arômes","colour, flavour"),"#8c1d40")+fD(1.5,fChip(70,110,w3("pochi tannini","peu de tanins","little tannin"))))},
 {h:I3("La temperatura: 20–32 °C","La température : 20–32 °C","Temperature: 20–32 °C"),
  c:I3("I rossi fermentano di solito tra 20 e 32 °C, più dei bianchi, per estrarre colore, aromi e tannini, ma senza superare i 35 °C, che ucciderebbero i lieviti. Controllando la temperatura il produttore decide quanto estrarre: per esempio, siccome i tannini si sciolgono meglio quando l'alcol sale, può limitarli abbassando la temperatura verso la fine della fermentazione.",
   "Les rouges fermentent en général entre 20 et 32 °C, plus que les blancs, pour extraire couleur, arômes et tanins, sans dépasser 35 °C, qui tuerait les levures. En contrôlant la température, le vinificateur décide de l'extraction : par exemple, comme les tanins se dissolvent mieux quand l'alcool monte, il peut les limiter en baissant la température vers la fin de la fermentation.",
   "Red wines usually ferment between 20 and 32 °C, warmer than whites, to extract colour, flavour and tannin, but must not exceed 35 °C, which could kill the yeast. By controlling temperature the winemaker steers extraction: for example, since tannins become more soluble as alcohol rises, extraction can be reduced by lowering the temperature towards the end of fermentation."),
  v:()=>fSvg(STEEL(40,40,100,130,{col:RED,lv:.8,bub:12,cap:1})+fThermo(160,60,"20–32 °C",.7)+fD(1,fChip(250,60,w3("mai oltre 35 °C","jamais plus de 35 °C","never above 35 °C"),"#b5334a"))+fD(2,fChip(250,120,w3("fine: più fresco = meno tannino","fin : plus frais = moins de tanin","end: cooler = less tannin"),"#2b7a75")))},
 {h:I3("Il cappello","Le chapeau de marc","The cap"),
  c:I3("Durante la fermentazione bucce e polpa salgono in superficie formando una massa spessa: il cappello. Se lo si lascia galleggiare si estrae poco colore, poco aroma e pochi tannini. Ci sono quindi molte tecniche di gestione del cappello, da combinare o usare in momenti diversi; si regola l'estrazione con la durata e con il numero di interventi al giorno.",
   "Pendant la fermentation, peaux et pulpe montent à la surface et forment une masse épaisse : le chapeau. Si on le laisse flotter, on extrait peu de couleur, d'arômes et de tanins. Il existe donc de nombreuses techniques de gestion du chapeau, à combiner ou utiliser à différents moments ; on règle l'extraction par la durée et par le nombre d'interventions par jour.",
   "During fermentation skins and pulp rise to the surface to form a thick mass: the cap. Left to float, it gives up little colour, flavour or tannin. There are many cap management techniques, which may be combined or used at different stages; extraction is controlled by the duration and number of times each is used per day."),
  v:()=>fSvg(STEEL(110,40,100,130,{col:RED,lv:.82,bub:14})+`<rect x="115" y="62" width="90" height="0" fill="#3d0f22"><animate attributeName="height" from="0" to="22" dur="2.5s" fill="freeze"/></rect>`+fCall(205,70,260,50,w3("cappello","chapeau","cap"),2.6))},
 {h:I3("Le follature","Le pigeage","Punching down"),
  c:I3("Un tempo si spingeva giù il cappello a mano, con pale montate su bastoni: lavoro pericoloso, perché si rischiava l'intossicazione da anidride carbonica. Oggi lo stesso effetto si ottiene con pale meccaniche, anche su binari che passano da una vasca all'altra. È una tecnica molto diffusa ed efficace per estrarre colore e tannini, ma non va esagerata, soprattutto a fine fermentazione, quando i tannini si estraggono più facilmente: il vino diventerebbe troppo amaro e astringente.",
   "Autrefois on enfonçait le chapeau à la main, avec des pelles au bout de bâtons : un travail dangereux, car on risquait l'intoxication au gaz carbonique. Aujourd'hui le même effet s'obtient avec des pigeurs mécaniques, parfois sur rails passant d'une cuve à l'autre. C'est une technique très répandue et efficace pour extraire couleur et tanins, mais il ne faut pas en abuser, surtout en fin de fermentation, quand les tanins s'extraient plus facilement : le vin deviendrait trop amer et astringent.",
   "Traditionally the cap was punched down by hand with paddles on sticks: a dangerous job because workers could be overcome by carbon dioxide. Today mechanical paddles do the same, sometimes on overhead rails moving from tank to tank. It is widely used and very effective at extracting colour and tannin, but must not be overdone, especially at the end of fermentation when tannins are extracted more easily: the wine would become overly bitter and astringent."),
  v:()=>fSvg(STEEL(60,50,100,120,{col:RED,lv:.8,cap:1,bub:8,punch:1})+fMan(220,170,1.2,"#8c1d40")+`<text x="110" y="40" font-size="10" fill="#bfe3f5" font-weight="800" text-anchor="middle">CO₂<animate attributeName="y" from="60" to="20" dur="2s" repeatCount="indefinite"/><animate attributeName="opacity" values="1;0" dur="2s" repeatCount="indefinite"/></text>`+fD(1.5,fChip(240,50,w3("non esagerare a fine fermentazione","sans excès en fin de fermentation","don't overwork at the end"),"#b5334a")))},
 {h:I3("I rimontaggi","Les remontages","Pumping over"),
  c:I3("Si preleva il mosto in fermentazione dal fondo della vasca e lo si pompa sopra il cappello, bagnandolo. È una tecnica molto usata per estrarre, e ha due vantaggi in più: disperde il calore e ossigena il mosto. Si può fare a mano o con impianti fissi dotati di un getto orientabile.",
   "On prélève le moût en fermentation au bas de la cuve et on le pompe sur le chapeau pour l'arroser. Technique très utilisée pour l'extraction, elle a deux avantages en plus : elle dissipe la chaleur et oxygène le moût. On peut le faire à la main ou avec des installations fixes munies d'un jet orientable.",
   "Fermenting juice is drawn off from the bottom of the vat and pumped up over the top, wetting the cap. A popular extraction technique, it has two further benefits: it dissipates heat and oxygenates the juice. It can be done by hand or with fixed pipework and a movable spray."),
  v:()=>fSvg(STEEL(90,50,110,120,{col:RED,lv:.8,cap:1,bub:8,pump:1})+fChip(60,40,w3("disperde il calore","dissipe la chaleur","releases heat"))+fChip(260,170,w3("ossigena","oxygène","oxygenates")))},
 {h:I3("Délestage e vinificatori rotativi","Délestage et cuves rotatives","Rack and return and rotary fermenters"),
  c:I3("Nel délestage, rack and return, si svuota il mosto in fermentazione in un'altra vasca lasciando il cappello indietro, poi lo si ripompa sopra il cappello. Si fa una o due volte per fermentazione, perché è molto estrattivo, e come il rimontaggio raffredda bene. Nei vinificatori rotativi la fermentazione avviene in serbatoi orizzontali che girano, tenendo il mosto sempre a contatto con le bucce.",
   "Dans le délestage, on vide le moût en fermentation dans une autre cuve en laissant le chapeau derrière, puis on le repompe par-dessus le chapeau. On le fait une ou deux fois par fermentation, car il est très extractif, et comme le remontage il refroidit bien. Dans les cuves rotatives, la fermentation a lieu dans des cuves horizontales qui tournent, gardant le moût toujours au contact des peaux.",
   "In rack and return, délestage, the fermenting juice is drained into another vessel, leaving the cap behind, then pumped back over the cap. It is normally done only once or twice per fermentation because it is very extractive, and like pumping over it releases heat well. In rotary fermenters fermentation takes place in rotating horizontal tanks that keep the juice constantly in contact with the skins."),
  v:()=>fSvg(STEEL(20,40,90,120,{col:RED,lv:.3,cap:1})+`<rect x="25" y="96" width="80" height="12" fill="#3d0f22"/>`+fArrow("M110 150Q150 170 170 150",null,1)+STEEL(170,80,70,90,{col:RED,lv:.8})+fArrow("M205 76Q160 20 65 90",null,1)+`<g transform="translate(280 140)"><g><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="4s" repeatCount="indefinite"/><ellipse rx="34" ry="22" fill="url(#fst)" stroke="#5c646b"/><path d="M-30 0H30" stroke="#5a0f24" stroke-width="10"/></g></g>`+fT(280,186,w3("rotativo","rotative","rotary"),9))},
 {h:I3("I recipienti di fermentazione","Les cuves de fermentation","Fermentation vessels"),
  c:I3("Per gestire il cappello i rossi fermentano di solito in grandi recipienti, spesso aperti in alto per lavorare facilmente le bucce, di rovere, cemento o acciaio. Fermentare i rossi in barrique non è pratico: sarebbe quasi impossibile mantenere un buon contatto tra bucce e mosto.",
   "Pour gérer le chapeau, les rouges fermentent en général dans de grandes cuves, souvent ouvertes en haut pour travailler facilement les peaux, en chêne, béton ou inox. Fermenter les rouges en barrique est peu pratique : il serait presque impossible de garder un bon contact entre peaux et jus.",
   "To manage the cap, reds are usually fermented in large vessels, often open-topped so the skins can be worked easily, made of oak, concrete or stainless steel. Fermenting reds in barrels is impractical: it would be almost impossible to keep enough contact between skins and juice."),
  v:()=>fSvg(`<path d="M20 70H100L94 170H26Z" fill="url(#fwood)" stroke="#4e321c"/><rect x="26" y="74" width="68" height="14" fill="#3d0f22"/>`+`<rect x="120" y="70" width="80" height="100" fill="#b8b1a6" stroke="#8e877c"/><rect x="124" y="74" width="72" height="14" fill="#3d0f22"/>`+STEEL(220,50,80,120,{col:RED,lv:.8,cap:1})+fT(60,186,w3("rovere","chêne","oak"),9)+fT(160,186,w3("cemento","béton","concrete"),9)+fT(260,186,w3("acciaio","inox","steel"),9))},
 {h:I3("La macerazione dopo la fermentazione","La macération post-fermentaire","Post-fermentation maceration"),
  c:I3("Lasciare il vino sulle bucce dopo la fermentazione estrae altri tannini, il che può essere voluto o no: la durata dipende dallo stile. Alcuni produttori hanno notato che macerazioni molto lunghe danno tannini più vellutati.",
   "Laisser le vin sur les peaux après la fermentation extrait davantage de tanins, ce qui peut être souhaité ou non : la durée dépend du style. Certains vinificateurs ont constaté que de très longues macérations donnent des tanins plus soyeux.",
   "Leaving the wine on its skins after fermentation extracts more tannin, which may or may not be desirable: how long depends on the style. Some winemakers have found that very long post-fermentation macerations give a smoother tannin structure."),
  v:()=>fSvg(STEEL(90,44,100,120,{col:RED,colTo:"#4d0c20",lv:.8,cap:1})+fClock(250,80,w3("giorni · settimane","jours · semaines","days · weeks")))},
 {h:I3("Vino fiore e vino di pressa","Vin de goutte et vin de presse","Free-run wine and press wine"),
  c:I3("Finita la macerazione, il vino che scorre da solo, il vino fiore, viene separato dalle bucce, e la massa rimasta va in pressa: è il vino di pressa. All'inizio è simile al vino fiore, ma continuando a pressare diventa più scuro e più tannico. Alcuni separano le frazioni di pressatura e usano le ultime per regolare colore e tannini nell'assemblaggio finale.",
   "La macération terminée, le vin qui s'écoule seul, le vin de goutte, est séparé des peaux, et le marc restant part au pressoir : c'est le vin de presse. Au début il ressemble au vin de goutte, mais à mesure qu'on presse il devient plus foncé et plus tannique. Certains séparent les fractions de presse et utilisent les dernières pour ajuster couleur et tanins dans l'assemblage final.",
   "When maceration ends, the wine that runs off freely, the free-run wine, is drawn off the skins and the remaining mass is pressed: this is press wine. At first it resembles the free-run wine, but as pressing continues it becomes deeper in colour and higher in tannin. Some winemakers keep the press fractions separate and use the later ones to adjust colour and tannin in the final blend."),
  v:()=>fSvg(STEEL(20,44,80,110,{col:RED,lv:.6,lab:w3("vino fiore","vin de goutte","free run")})+`<path d="M100 140h18" stroke="#6c757d" stroke-width="5"/>`+fDrops(118,144,170,RED,4)+fPress(170,70,"#5a0f24","#3d0f22")+fT(225,160,w3("vino di pressa: più scuro e tannico","vin de presse : plus foncé et tannique","press wine: darker, more tannic"),8.5))},
 {h:I3("Il grappolo intero","La vendange entière","Whole-bunch fermentation"),
  c:I3("Alcuni produttori mettono in fermentazione anche grappoli interi, non pigiati: a volte tutta la vasca, a volte una piccola parte per un tocco più discreto. I raspi devono essere ben maturi, altrimenti danno tannini amari. L'obiettivo è creare per l'uva intera un ambiente senza ossigeno. Accadono due cose: dentro l'acino si forma un po' di alcol senza lieviti, la fermentazione intracellulare, e soprattutto nascono aromi fruttati particolari che danno a questi vini un carattere unico.",
   "Certains vinificateurs mettent aussi en fermentation des grappes entières, non foulées : parfois toute la cuve, parfois une petite partie pour une touche plus discrète. Les rafles doivent être bien mûres, sinon elles donnent des tanins amers. Le but est de créer pour le raisin entier un milieu sans oxygène. Deux choses se produisent : un peu d'alcol se forme dans la baie sans levures, la fermentation intracellulaire, et surtout naissent des arômes fruités particuliers qui donnent à ces vins un caractère unique.",
   "Some winemakers include whole, uncrushed bunches in the fermentation: sometimes the whole vat, sometimes a small share for a subtler effect. The stems must be fully ripe, or their tannins give a bitter taste. The aim is an oxygen-free environment for the intact fruit. Two things happen: the berries make some alcohol inside their cells without any yeast, intracellular fermentation, and, more importantly, distinctive fruity aromas form inside the berry, giving these wines unique qualities."),
  v:()=>fSvg(`<g transform="translate(160 100)"><circle r="60" fill="#5a1f4a"/><circle r="52" fill="#b25a7a"/>${[0,1,2,3,4,5].map(i=>`<circle cx="${Math.cos(i)*26}" cy="${Math.sin(i*2)*20}" r="4" fill="#f3e3c3" opacity=".8"><animate attributeName="r" values="2;5;2" dur="2s" begin="${i*.3}s" repeatCount="indefinite"/></circle>`).join("")}</g>`+fChip(160,186,w3("fermentazione intracellulare, senza lieviti","fermentation intracellulaire, sans levures","intracellular fermentation, no yeast"),"#d4a23a","#2a1b20")+fChip(60,40,w3("niente O₂","sans O₂","no O₂")))},
 {h:I3("La macerazione carbonica","La macération carbonique","Carbonic maceration"),
  c:I3("Si mettono solo grappoli interi e non pigiati in vasche riempite di anidride carbonica per togliere tutto l'ossigeno: parte la fermentazione intracellulare. Quando l'alcol nell'acino arriva a circa il 2 per cento, le bucce si spaccano e liberano il succo. Di solito a questo punto si pressa e i lieviti finiscono la fermentazione senza bucce. Si estrae colore ma pochi tannini: vini morbidi e fruttati, con note di kirsch, banana, chewing-gum e una spezia simile alla cannella.",
   "On place uniquement des grappes entières non foulées dans des cuves remplies de gaz carbonique pour chasser tout l'oxygène : la fermentation intracellulaire démarre. Quand l'alcool dans la baie atteint environ 2 %, les peaux éclatent et libèrent le jus. En général on presse alors et les levures terminent la fermentation sans les peaux. On extrait de la couleur mais peu de tanins : des vins souples et fruités, aux notes de kirsch, banane, chewing-gum et d'une épice proche de la cannelle.",
   "Only whole, uncrushed bunches go into vats that are filled with carbon dioxide to remove all oxygen: intracellular fermentation begins. When the alcohol inside the berry reaches about 2%, the skins split and release their juice. The grapes are generally pressed at this point and yeast complete the fermentation off the skins. Colour is extracted but little tannin: soft, fruity wines with kirsch, banana, bubblegum and cinnamon-like spice."),
  v:()=>fSvg(STEEL(80,30,120,140,{col:"#2e1a26",lv:.8})+Array.from({length:6},(_,i)=>`<g transform="translate(${100+(i%3)*30} ${70+Math.floor(i/3)*40})">${fBunch(0,0,1.2,"#a04a7e")}</g>`).join("")+`<rect x="85" y="46" width="110" height="120" fill="rgba(159,211,240,.25)"/>`+fChip(140,22,"CO₂","#2b7a75")+fD(1.5,fChip(260,80,"≈ 2% → "+w3("pressatura","pressurage","press")))+fD(2.4,fChip(260,130,w3("kirsch · banana · chewing-gum","kirsch · banane · chewing-gum","kirsch · banana · bubblegum"),"#d4a23a","#2a1b20")))},
 {h:I3("La macerazione semicarbonica","La macération semi-carbonique","Semi-carbonic maceration"),
  c:I3("Simile, ma senza riempire la vasca di anidride carbonica. Si riempie di grappoli interi: quelli sul fondo si schiacciano sotto il peso degli altri, liberano succo e i lieviti indigeni lo fanno fermentare. L'anidride carbonica prodotta riempie la vasca e gli acini ancora interi fanno la macerazione carbonica. Quando si spaccano, si pressa e i lieviti finiscono senza bucce. Alcuni grandi Pinot Noir si fanno così ma continuando sulle bucce: con follature progressive nei primi giorni si rompono gli acini, la parte carbonica diminuisce e la fermentazione prosegue sulle bucce. Gli aromi si integrano meglio e il frutto è più fresco.",
   "Proche, mais sans remplir la cuve de gaz carbonique. On la remplit de grappes entières : celles du fond sont écrasées sous le poids des autres, libèrent du jus et les levures indigènes le font fermenter. Le gaz carbonique produit remplit la cuve et les baies encore intactes subissent la macération carbonique. Quand elles éclatent, on presse et les levures terminent sans les peaux. Certains grands Pinots Noirs se font ainsi mais en continuant sur les peaux : par des pigeages progressifs les premiers jours on brise les baies, la part carbonique diminue et la fermentation se poursuit sur peaux. Les arômes s'intègrent mieux et le fruit est plus frais.",
   "Similar, but the vat is not filled with carbon dioxide. It is filled with whole bunches: those at the bottom are crushed by the weight above, releasing juice that ambient yeast start to ferment. The carbon dioxide produced fills the vat and the intact berries undergo carbonic maceration. When they split, the grapes are pressed and yeast finish off the skins. Some notable Pinot Noirs are made this way but continue on the skins: progressive punch-downs over the first days break up the berries, carbonic maceration decreases and fermentation continues on the skins. The aromas integrate better and the fruit is fresher."),
  v:()=>fSvg(STEEL(80,30,120,140,{col:"#2e1a26",lv:.85})+Array.from({length:6},(_,i)=>`<g transform="translate(${100+(i%3)*30} ${60+Math.floor(i/3)*36})">${fBunch(0,0,1.1,"#a04a7e")}</g>`).join("")+`<rect x="85" y="136" width="110" height="30" fill="#7a1530"/>`+[0,1,2].map(i=>`<circle cx="${110+i*30}" cy="150" r="2" fill="#fff"><animate attributeName="cy" from="150" to="50" dur="${2+i*.4}s" repeatCount="indefinite"/></circle>`).join("")+fCall(190,150,260,170,w3("sotto: schiacciati, lieviti","au fond : écrasés, levures","bottom: crushed, yeast"),.5)+fCall(190,80,260,50,w3("sopra: interi, carbonica","en haut : entiers, carbonique","top: whole, carbonic"),1.4))},
 {h:I3("Grappoli interi con uva pigiata","Grappes entières et raisin foulé","Whole bunches with crushed fruit"),
  c:I3("Un'altra variante è mescolare fin dall'inizio grappoli interi e uva pigiata nella stessa vasca. I grappoli interi non sono coperti di anidride carbonica, ma restano in gran parte sommersi e lontani dall'ossigeno, quindi avviene la fermentazione intracellulare. Con le follature vengono schiacciati poco a poco. Più grappoli interi si mettono all'inizio, più si ottiene carattere «carbonico»: la tecnica darebbe una consistenza più setosa e un frutto più vivace e fresco.",
   "Autre variante : mélanger dès le départ grappes entières et raisin foulé dans la même cuve. Les grappes entières ne sont pas couvertes de gaz carbonique, mais restent en grande partie immergées et à l'abri de l'oxygène, donc la fermentation intracellulaire a lieu. Elles sont écrasées peu à peu par les pigeages. Plus on met de grappes entières au départ, plus on obtient de caractère « carbonique » : la technique donnerait une texture plus soyeuse et un fruit plus vif et frais.",
   "A further variation mixes whole bunches with crushed grapes in the vat from the start. The whole bunches are not blanketed in CO₂, but are largely submerged and kept from oxygen, so intracellular fermentation takes place. They are progressively crushed as the cap is punched down. The more whole bunches at the start, the more 'carbonic' character: the technique is thought to give a silkier texture and brighter, fresher fruit."),
  v:()=>fSvg(STEEL(100,30,120,140,{col:RED,lv:.85,punch:1})+[0,1,2].map(i=>`<g transform="translate(${125+i*35} 110)">${fBunch(0,0,1.1,"#a04a7e")}</g>`).join("")+fChip(60,60,w3("+ grappoli = + carbonico","+ grappes = + carbonique","+ bunches = + carbonic"))+fChip(270,150,w3("setoso, fresco","soyeux, frais","silky, fresh"),"#d4a23a","#2a1b20"))}
]},
{id:"red2",sec:"c",ch:"red",ic:"sat",t:I3("Rossi e rosati: affinamento, stili e vitigni","Rouges et rosés : élevage, styles et cépages","Reds and rosés: maturation, styles and grapes"),s:[
 {h:I3("Affinamento, assemblaggio e chiarifica dei rossi","Élevage, assemblage et clarification des rouges","Maturation, blending and clarification of reds"),
  c:I3("La scelta più importante è usare o no il rovere. Quasi tutti i rossi fanno la malolattica e, essendo più robusti, beneficiano meno dei bianchi del contatto con le fecce. Il rovere è molto usato, in botti o con doghe e trucioli; la moda dei grandi rossi interamente in barrique nuove sta passando, a favore di botti di età e dimensioni diverse, anche se i vini migliori restano più a lungo e con più legno nuovo. L'assemblaggio di varietà diverse corregge colore, corpo, tannini, acidità o aromi; si usano le frazioni di pressatura, botti di età e tostature diverse, o vino in acciaio per un legno più discreto. Quasi tutti i rossi si chiarificano e si filtrano, ma alcuni lo evitano e si affidano alla lenta sedimentazione dei lunghi affinamenti.",
   "Le choix le plus important est d'utiliser ou non le chêne. Presque tous les rouges font la malolactique et, plus robustes, profitent moins que les blancs du contact avec les lies. Le chêne est très utilisé, en fûts ou avec douelles et copeaux ; la mode des grands rouges entièrement en barriques neuves recule, au profit de fûts d'âges et de tailles variés, même si les meilleurs vins restent plus longtemps et avec plus de bois neuf. L'assemblage de cépages corrige couleur, corps, tanins, acidité ou arômes ; on utilise les fractions de presse, des fûts d'âges et de chauffes différents, ou du vin en inox pour un boisé plus discret. Presque tous les rouges sont collés et filtrés, mais certains s'en passent et comptent sur la lente sédimentation des longs élevages.",
   "The most important choice is whether to use oak. Almost all reds go through MLF and, being more robust, benefit less than whites from lees contact. Oak is widely used, as barrels or as staves and chips; the trend for premium reds aged entirely in new barriques is declining, in favour of vessels of varied ages and larger sizes, though the best wines still get longer ageing and more new oak. Blending varieties adjusts colour, body, tannin, acidity or flavour; press fractions, barrels of different ages and toasts, or steel-aged wine for subtler oak, are also used. Most reds are fined and/or filtered, though some winemakers avoid this and rely on the slow sedimentation of long maturation."),
  v:()=>fSvg([0,1,2].map(i=>fBarrel(60+i*70,80,.9)).join("")+`<ellipse cx="270" cy="80" rx="40" ry="36" fill="url(#fwood)" stroke="#4e321c"/>`+fT(160,30,w3("età e dimensioni diverse","âges et tailles variés","varied ages and sizes"),10,"#f3cd8a")+fD(1.5,fChip(160,150,w3("assemblaggio: colore, corpo, tannino","assemblage : couleur, corps, tanin","blending: colour, body, tannin"))))},
 {h:I3("I rossi economici","Les rouges bon marché","Inexpensive red wines"),
  c:I3("Nascono in zone calde, soleggiate e asciutte, con Cabernet Sauvignon, Merlot, Syrah e Grenache, che danno colore anche con rese alte; il Pinot Noir, difficile e da clima fresco, è poco adatto. Lo stile è fruttato e poco tannico: lavorazione protettiva con solforosa, diraspatura e pigiatura, spesso aggiunta di acido tartarico, a volte una breve macerazione a freddo. Si fermenta con lieviti selezionati a 22–25 °C, in vasche statiche o rotative, senza lavorare troppo il cappello e senza macerazione dopo la fermentazione; al massimo si macera una piccola parte da assemblare. Anche macerazione carbonica o semicarbonica, per Grenache e Beaujolais base. Poi acciaio, o pochi mesi in botti di secondo o terzo passaggio, o trucioli; stabilizzazione, collaggio, filtrazione sterile e solforosa all'imbottigliamento.",
   "Ils naissent dans des zones chaudes, ensoleillées et sèches, avec Cabernet Sauvignon, Merlot, Syrah et Grenache, qui donnent de la couleur même à haut rendement ; le Pinot Noir, difficile et de climat frais, convient mal. Le style est fruité et peu tannique : travail protecteur au soufre, éraflage et foulage, souvent ajout d'acide tartrique, parfois une courte macération à froid. On fermente avec des levures sélectionnées à 22–25 °C, en cuves statiques ou rotatives, sans trop travailler le chapeau et sans macération post-fermentaire ; tout au plus on macère une petite partie à assembler. Aussi macération carbonique ou semi-carbonique, pour la Grenache et le Beaujolais simple. Puis inox, ou quelques mois en fûts de deuxième ou troisième vin, ou copeaux ; stabilisation, collage, filtration stérile et soufre à la mise en bouteille.",
   "They come from warm, sunny, dry areas, using Cabernet Sauvignon, Merlot, Syrah and Grenache, which give colour even at high yields; Pinot Noir, difficult and suited to cool climates, is a poor fit. The style is fruity and low in tannin: protective handling with SO₂, destemming and crushing, often added tartaric acid, sometimes a short cold soak. Fermentation uses commercial yeast at 22–25 °C, in static or rotary vessels, with light cap work and no post-fermentation maceration; at most a small portion is macerated and blended back. Carbonic or semi-carbonic maceration is also used, for Grenache and basic Beaujolais. Then steel, or a few months in second- or third-fill barrels, or chips; stabilisation, fining, sterile filtration and SO₂ at bottling."),
  v:()=>fSvg(fFlow([{t:I3("+ acido tartarico","+ acide tartrique","+ tartaric acid")},{t:"22–25 °C"},{t:I3("cappello poco lavorato","chapeau peu travaillé","light cap work")},{t:I3("niente macerazione post","pas de macération post","no post-maceration")},{t:I3("acciaio o botti usate o trucioli","inox, fûts usagés ou copeaux","steel, used barrels or chips"),o:1},{t:I3("filtrazione sterile","filtration stérile","sterile filtration")}],-1,{per:3,stag:1,y0:40,bh:40,gy:24}))},
 {h:I3("Cabernet Sauvignon","Cabernet Sauvignon","Cabernet Sauvignon"),
  c:I3("Buccia spessa, quindi tanto colore, aroma e tannino; matura tardi, e nelle zone più fresche può restare con tannini astringenti e note erbacee. Nell'Haut-Médoc dà vini longevi, con tannini serrati da giovani e note di cedro e foglia di ribes, quasi sempre con un po' di Merlot. Nel Nuovo Mondo, come Napa, Coonawarra, Margaret River, Hawke's Bay, Stellenbosch e Colchagua, è più pieno e maturo. In cantina si diraspa e pigia, i raspi darebbero note erbacee; si può macerare a freddo per il colore. Si fermenta a 26–30 °C, evitando estrazioni forti a fine fermentazione, e una macerazione post può ammorbidire i tannini. Regge bene il rovere nuovo: barrique francesi da 225 litri, di solito 12–18 mesi; spesso si assembla con Merlot o, in Australia, Shiraz.",
   "Peau épaisse, donc beaucoup de couleur, d'arômes et de tanins ; il mûrit tard et, dans les zones plus fraîches, peut garder des tanins astringents et des notes herbacées. Dans le Haut-Médoc il donne des vins de garde, aux tanins serrés dans leur jeunesse et aux notes de cèdre et de feuille de cassis, presque toujours avec un peu de Merlot. Dans le Nouveau Monde, Napa, Coonawarra, Margaret River, Hawke's Bay, Stellenbosch, Colchagua, il est plus ample et mûr. Au chai on éraffle et foule, les rafles donneraient des notes herbacées ; on peut macérer à froid pour la couleur. On fermente à 26–30 °C, en évitant les extractions fortes en fin de fermentation, et une macération post peut assouplir les tanins. Il supporte bien le chêne neuf : barriques françaises de 225 litres, en général 12 à 18 mois ; souvent assemblé avec du Merlot ou, en Australie, de la Shiraz.",
   "Thick-skinned, so plenty of colour, flavour and tannin; late-ripening, and in cooler places it can stay astringent and herbaceous. In the Haut-Médoc it makes long-lived wines with grippy young tannins and cedar and blackcurrant-leaf notes, usually blended with some Merlot. In the New World, Napa, Coonawarra, Margaret River, Hawke's Bay, Stellenbosch, Colchagua, it is fuller and riper. In the winery it is destemmed and crushed, as stems give herbaceous notes; a cold soak may maximise colour. It ferments at 26–30 °C, avoiding heavy extraction near the end, and post-fermentation maceration can soften tannins. It suits new oak: 225-litre French barriques, typically 12–18 months; often blended with Merlot or, in Australia, Shiraz."),
  v:()=>fSvg(`<g transform="translate(70 90)">${fBunch(0,0,2.6,"#2a0f2a")}</g>`+fT(70,40,"Cabernet Sauvignon",11)+fD(.6,fBox(150,30,150,30,"26–30 °C · "+w3("macerazione post","macération post","post-maceration")))+fD(1.2,fBox(150,70,150,30,w3("barrique francese 12–18 mesi","barrique française 12–18 mois","French barrique 12–18 months"),{fill:"rgba(138,90,51,.6)"}))+fD(1.8,fBox(150,110,150,30,"+ Merlot / Shiraz",{fill:"rgba(140,29,64,.6)"})))},
 {h:I3("Merlot","Merlot","Merlot"),
  c:I3("È l'altra grande uva di Bordeaux: germoglia e matura prima del Cabernet, con cui si assembla spesso, e domina a Saint-Émilion e Pomerol. I migliori seguono due stili. Il primo, «internazionale», da uve raccolte il più tardi possibile: colore viola intenso, mora e prugna concentrate, tannini vellutati, spesso rovere nuovo; si trova nel Nuovo Mondo, nel sud della Francia e in alcune tenute bordolesi. Il secondo, raro fuori da Bordeaux, da uve raccolte prima: corpo e alcol medi, più acidità, frutto rosso fresco e note vegetali. La vinificazione è simile al Cabernet, ma le bucce più morbide richiedono meno estrazione; 12–18 mesi di rovere sono comuni.",
   "C'est l'autre grand cépage de Bordeaux : il débourre et mûrit avant le Cabernet, avec lequel on l'assemble souvent, et domine à Saint-Émilion et Pomerol. Les meilleurs suivent deux styles. Le premier, « international », issu de raisins cueillis le plus tard possible : couleur violette intense, mûre et prune concentrées, tanins veloutés, souvent chêne neuf ; on le trouve dans le Nouveau Monde, le sud de la France et certains châteaux bordelais. Le second, rare hors de Bordeaux, issu de raisins cueillis plus tôt : corps et alcool moyens, plus d'acidité, fruit rouge frais et notes végétales. La vinification ressemble à celle du Cabernet, mais les peaux plus souples demandent moins d'extraction ; 12 à 18 mois de chêne sont courants.",
   "It is Bordeaux's other great grape: it buds and ripens earlier than Cabernet, with which it is often blended, and dominates in Saint-Émilion and Pomerol. The best follow two styles. The 'international' one, from grapes picked as late as possible: intense purple colour, concentrated blackberry and plum, velvety tannins, often new oak; found in the New World, southern France and some Bordeaux estates. The other, rare outside Bordeaux, from earlier picking: medium body and alcohol, higher acidity, fresh red fruit and leafy notes. Winemaking is similar to Cabernet, but the softer skins need less rigorous extraction; 12–18 months in oak is common."),
  v:()=>fSvg(`<g transform="translate(70 90)">${fBunch(0,0,2.6,"#3d1238")}</g>`+fT(70,40,"Merlot",11)+fD(.8,fBox(150,30,150,50,w3("internazionale: tardivo, viola, prugna, rovere nuovo","international : tardif, violet, prune, chêne neuf","international: late, purple, plum, new oak"),{fill:"rgba(107,45,92,.6)"}))+fD(1.6,fBox(150,94,150,50,w3("bordolese: precoce, frutto rosso, fresco","bordelais : précoce, fruit rouge, frais","Bordeaux: earlier, red fruit, fresh"),{fill:"rgba(181,51,74,.45)"}))+fChip(70,180,"Saint-Émilion · Pomerol"))},
 {h:I3("Pinot Noir","Pinot Noir","Pinot Noir"),
  c:I3("Germoglia e matura presto, ha buccia sottile e moltissimi cloni; va dal leggero e fruttato, di ciliegia rossa, al complesso e terroso, di spezie e sottobosco. Colore e tannini sono difficili da estrarre: bisogna estrarre al massimo senza lavorare troppo, o si perde l'eleganza. Ama i climi freschi e moderati: la Borgogna, il Baden, e nel Nuovo Mondo Carneros, Sonoma, Martinborough, Marlborough, Central Otago, Yarra, Mornington, Tasmania, Walker Bay e Casablanca; troppo caldo dà note di marmellata. Si diraspa con macerazione a freddo, oppure si usano sempre più grappoli interi per frutto rosso e note floreali. Spesso fermenta oltre 30 °C, quasi mai con macerazione post; affina 12–24 mesi in botti per lo più di secondo o terzo passaggio, e di solito non si assembla con altre varietà.",
   "Il débourre et mûrit tôt, a la peau fine et de très nombreux clones ; il va du léger et fruité, cerise rouge, au complexe et terreux, épices et sous-bois. Couleur et tanins sont difficiles à extraire : il faut extraire au maximum sans surtravailler, sinon on perd l'élégance. Il aime les climats frais et modérés : la Bourgogne, le Bade, et dans le Nouveau Monde Carneros, Sonoma, Martinborough, Marlborough, Central Otago, Yarra, Mornington, Tasmanie, Walker Bay et Casablanca ; trop de chaleur donne des notes confiturées. On éraffle avec macération à froid, ou on utilise de plus en plus de grappes entières pour le fruit rouge et le floral. Il fermente souvent au-delà de 30 °C, rarement avec macération post ; il s'élève 12 à 24 mois en fûts surtout de deuxième ou troisième vin, et ne s'assemble généralement pas avec d'autres cépages.",
   "Early budding and ripening, thin-skinned, with many clones; it ranges from light and fruity, red cherry, to complex and earthy, spice and forest floor. Colour and tannin are hard to extract: the aim is maximum extraction without overworking, or elegance is lost. It suits cool and moderate climates: Burgundy, Baden, and in the New World Carneros, Sonoma, Martinborough, Marlborough, Central Otago, Yarra, Mornington, Tasmania, Walker Bay and Casablanca; too much heat gives jammy flavours. It may be destemmed with a cold soak, or increasingly includes whole bunches for red fruit and floral notes. It often ferments above 30 °C, rarely with post-fermentation maceration; it ages 12–24 months, mostly in second- or third-fill barrels, and is not usually blended with other varieties."),
  v:()=>fSvg(`<g transform="translate(70 90)">${fBunch(0,0,2.4,"#4e1b44")}</g>`+fT(70,40,"Pinot Noir",11)+fD(.6,fBox(150,30,150,30,w3("grappoli interi · > 30 °C","grappes entières · > 30 °C","whole bunches · > 30 °C")))+fD(1.2,fBox(150,70,150,30,w3("12–24 mesi, poco legno nuovo","12–24 mois, peu de bois neuf","12–24 months, little new oak"),{fill:"rgba(138,90,51,.6)"}))+fD(1.8,fBox(150,110,150,30,w3("ciliegia → sottobosco","cerise → sous-bois","cherry → forest floor"),{fill:"rgba(140,29,64,.6)"})))},
 {h:I3("Syrah / Shiraz","Syrah / Shiraz","Syrah / Shiraz"),
  c:I3("Acini piccoli con buccia spessa e scura; non matura nei climi molto freschi. Va dal medio corpo, pepe e frutto nero fresco, al pieno e morbido, frutto nero maturissimo e liquirizia, e i migliori invecchiano a lungo. Nel Rodano settentrionale, al limite freddo, i pendii a sud di Côte-Rôtie ed Hermitage danno vini pieni con pepe, poi carne e cuoio; in Linguadoca-Rossiglione si assembla con Grenache, Mourvèdre, Carignan e Cinsault. In Australia, la Shiraz di zone calde come Barossa e Hunter è morbida, terrosa e speziata, quella di zone fresche più tesa e pepata. Lo stile pieno nasce da uve molto mature, estrazione vigorosa e molto rovere nuovo; quello più sobrio da vendemmia anticipata, estrazione delicata, un po' di grappoli interi, lunga macerazione post e botti più grandi, 300–500 litri, e più vecchie.",
   "Petites baies à peau épaisse et sombre ; elle ne mûrit pas en climat très frais. Elle va du corps moyen, poivre et fruit noir frais, à l'ample et souple, fruit noir très mûr et réglisse, et les meilleures vieillissent longtemps. Dans le Rhône septentrional, à sa limite fraîche, les pentes sud de Côte-Rôtie et Hermitage donnent des vins amples au poivre, puis viande et cuir ; en Languedoc-Roussillon on l'assemble avec Grenache, Mourvèdre, Carignan et Cinsault. En Australie, la Shiraz des zones chaudes comme la Barossa et la Hunter est souple, terreuse et épicée, celle des zones fraîches plus tendue et poivrée. Le style ample vient de raisins très mûrs, d'une extraction vigoureuse et de beaucoup de chêne neuf ; le style plus retenu d'une vendange précoce, d'une extraction douce, d'un peu de grappes entières, d'une longue macération post et de fûts plus grands, 300–500 litres, et plus anciens.",
   "Small berries with thick, dark skins; it will not ripen in very cool climates. It ranges from medium-bodied with pepper and fresh black fruit to full and smooth with very ripe black fruit and liquorice, and the best age for a long time. In the Northern Rhône, at its cool limit, the south-facing slopes of Côte-Rôtie and Hermitage give fuller wines with pepper, then meat and leather; in Languedoc-Roussillon it is blended with Grenache, Mourvèdre, Carignan and Cinsault. In Australia, Shiraz from hot regions such as Barossa and Hunter is soft, earthy and spicy, from cooler ones leaner and peppery. The full style comes from very ripe grapes, vigorous extraction and much new oak; the restrained style from earlier picking, gentler extraction, some whole bunches, long post-fermentation maceration and larger, 300–500-litre, older barrels."),
  v:()=>fSvg(`<g transform="translate(70 90)">${fBunch(0,0,2.4,"#1f0a26")}</g>`+fT(70,40,"Syrah / Shiraz",11)+fD(.8,fBox(150,30,150,50,w3("pieno: uve stramature, estrazione forte, rovere nuovo","ample : raisins surmûris, extraction forte, chêne neuf","full: very ripe, strong extraction, new oak"),{fill:"rgba(107,45,92,.6)"}))+fD(1.6,fBox(150,94,150,50,w3("sobrio: raccolta precoce, grappoli interi, botti 300–500 l","retenu : récolte précoce, grappes entières, fûts 300–500 l","restrained: early pick, whole bunch, 300–500 l"),{fill:"rgba(79,168,162,.45)"}))+fChip(70,180,"Côte-Rôtie · Hermitage · Barossa"))},
 {h:I3("Grenache / Garnacha","Grenache / Garnacha","Grenache / Garnacha"),
  c:I3("Matura tardi e vuole climi caldi; tollera bene la siccità. Gli acini dolci e dalla buccia sottile danno vini alcolici, poco acidi, pieni, con tannini morbidi e frutto rosso. In Spagna, come Garnacha, si assembla con il Carignan nel Priorat e con il Tempranillo in Rioja, dove aggiunge profumo, corpo e alcol, e dà anche rosati. È la varietà più piantata del Rodano meridionale, al suo meglio a Châteauneuf-du-Pape con Syrah e Mourvèdre; in Australia le vecchie viti ad alberello di Barossa e McLaren Vale danno vini intensi di frutti rossi e pepe. Si diraspa e pigia, spesso con macerazione prefermentativa e a volte qualche grappolo intero; fermenta in vasche aperte di acciaio o cemento con follature delicate, di solito senza macerazione post, e affina in grandi botti vecchie, perché il rovere nuovo ne coprirebbe il frutto. Si assembla quasi sempre, con Carignan e Mourvèdre che portano freschezza, tannini e colore.",
   "Elle mûrit tard et demande des climats chauds ; elle tolère bien la sécheresse. Ses baies sucrées à peau fine donnent des vins alcooleux, peu acides, amples, aux tanins souples et au fruit rouge. En Espagne, sous le nom de Garnacha, on l'assemble avec le Carignan dans le Priorat et le Tempranillo en Rioja, où elle apporte parfum, corps et alcool, et elle donne aussi des rosés. C'est le cépage le plus planté du Rhône méridional, à son meilleur à Châteauneuf-du-Pape avec Syrah et Mourvèdre ; en Australie les vieilles vignes en gobelet de la Barossa et de McLaren Vale donnent des vins intenses de fruits rouges et de poivre. On éraffle et foule, souvent avec macération préfermentaire et parfois quelques grappes entières ; elle fermente en cuves ouvertes d'inox ou de béton avec des pigeages doux, en général sans macération post, et s'élève en grands vieux foudres, car le chêne neuf masquerait son fruit. Elle est presque toujours assemblée, avec Carignan et Mourvèdre qui apportent fraîcheur, tanins et couleur.",
   "Late-ripening, it needs warm or hot climates and tolerates drought well. Its sweet, thin-skinned grapes give wines high in alcohol, low in acidity, full-bodied, with soft tannins and red fruit. In Spain, as Garnacha, it is blended with Carignan in Priorat and with Tempranillo in Rioja, where it adds perfume, body and alcohol, and it also makes rosés. It is the most planted variety of the Southern Rhône, at its best in Châteauneuf-du-Pape with Syrah and Mourvèdre; in Australia old bush vines in Barossa and McLaren Vale give intense red berry and pepper flavours. It is destemmed and crushed, often with a pre-fermentation maceration and sometimes some whole bunches; it ferments in open-top steel or cement vats with gentle punch-downs, usually drained off at the end without post-maceration, and matures in large old foudres, since new oak would overwhelm the fruit. It is almost always blended, with Carignan and Mourvèdre adding freshness, tannin and colour."),
  v:()=>fSvg(fSun(280,34,14)+fGround("#b08a5a")+vForm("bush","canopy",70,172)+fT(70,30,"Grenache / Garnacha",11)+fD(.8,fBox(150,40,150,40,w3("vasche aperte, follature delicate","cuves ouvertes, pigeages doux","open vats, gentle punch-downs")))+fD(1.6,`<ellipse cx="225" cy="120" rx="34" ry="28" fill="url(#fwood)" stroke="#4e321c"/>`+fT(225,162,w3("grandi botti vecchie","grands vieux foudres","large old foudres"),9)),"summer")},
 {h:I3("I rosati","Les rosés","Rosé wines"),
  c:I3("Si fanno in tre modi, e quasi mai con il legno. Pressatura diretta: le uve nere si pigiano e si pressano come per un bianco; prendono un po' di colore dalle bucce, facendo attenzione a non estrarre tannini: sono i rosati più pallidi. Macerazione breve: le uve nere pigiate macerano per estrarre colore e aroma, più o meno a lungo secondo il colore e il tannino voluti, a volte fino all'inizio della fermentazione; poi il mosto fiore si separa e fermenta al fresco come un bianco. Assemblaggio: si aggiunge un po' di vino rosso a un bianco. Nell'UE è vietato, tranne per lo Champagne rosé, ma si usa per alcuni rosati economici del Nuovo Mondo.",
   "Ils se font de trois façons, et presque jamais avec du bois. Pressurage direct : les raisins noirs sont foulés et pressés comme pour un blanc ; ils prennent un peu de couleur aux peaux, en veillant à ne pas extraire de tanins : ce sont les rosés les plus pâles. Macération courte : les raisins noirs foulés macèrent pour extraire couleur et arômes, plus ou moins longtemps selon la couleur et le tanin voulus, parfois jusqu'au début de la fermentation ; puis le jus de goutte est séparé et fermente au frais comme un blanc. Assemblage : on ajoute un peu de vin rouge à un blanc. C'est interdit dans l'UE, sauf pour le Champagne rosé, mais utilisé pour certains rosés bon marché du Nouveau Monde.",
   "There are three methods, and oak is rarely used. Direct pressing: black grapes are crushed and pressed as for white wine; a little colour comes from the skins, taking care not to extract tannin: these are the palest rosés. Short maceration: crushed black grapes macerate to extract colour and flavour, for longer or shorter depending on the colour and tannin wanted, sometimes into the start of fermentation; then the free-run juice is drained off and fermented cool like a white. Blending: a little red wine is added to a white. This is not permitted in the EU, except for rosé Champagne, but is used for some inexpensive New World rosés."),
  v:()=>fSvg(fBox(10,24,96,40,w3("pressatura diretta","pressurage direct","direct pressing"))+fBox(112,24,96,40,w3("macerazione breve","macération courte","short maceration"))+fBox(214,24,96,40,w3("assemblaggio","assemblage","blending"),{dash:1})+fStemGlass(58,140,"white","#f6d5cc")+fStemGlass(160,140,"white","#f0a3a0")+fStemGlass(262,140,"white","#e88a90")+fD(1.6,fChip(262,186,w3("UE: solo Champagne","UE : seulement Champagne","EU: Champagne only"),"#b5334a")))}
]}
);
